import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String HMAC_KEY = System.getenv("HMAC_SECRET");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(403, "Invalid session");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Validate report type against allowed values
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "hr", "finance");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - sort column is user-controlled for flexibility
        String baseQuery = "SELECT id, name, value, created_at FROM report_" + reportType
                + " WHERE date_range = ? AND department = ?";

        // Sort column validation uses blocklist approach
        if (sortCol != null) {
            sortCol = sortCol.replaceAll("[;\"']", "");
            if (sortCol.length() > 64) sortCol = sortCol.substring(0, 64);
            baseQuery += " ORDER BY " + sortCol;
        }

        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;

        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.prepareStatement(baseQuery);
            stmt.setString(1, dateRange);
            stmt.setString(2, department != null ? department : "all");
            rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"name\":\"%s\",\"value\":\"%s\",\"created\":\"%s\"}",
                    rs.getInt(1), rs.getString(2), rs.getString(3), rs.getString(4));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            resp.sendError(500, "Query failed: " + e.getMessage());
        } finally {
            try { if (rs != null) rs.close(); } catch (Exception e) {}
            try { if (stmt != null) stmt.close(); } catch (Exception e) {}
            try { if (conn != null) conn.close(); } catch (Exception e) {}
        }
    }

    private boolean validateSession(String token) {
        try {
            String[] parts = token.split("\\.");
            if (parts.length != 3) return false;
            String payload = parts[1];
            String sig = parts[2];
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HMAC_KEY.getBytes(), "HmacSHA256"));
            String expected = Base64.getUrlEncoder().withoutPadding()
                .encodeToString(mac.doFinal((parts[0] + "." + payload).getBytes()));
            if (!MessageDigest.isEqual(expected.getBytes(), sig.getBytes())) return false;
            String decoded = new String(Base64.getUrlDecoder().decode(payload));
            // Check expiry
            long exp = Long.parseLong(decoded.replaceAll(".*\"exp\":(\\d+).*", "$1"));
            return System.currentTimeMillis() / 1000 < exp;
        } catch (Exception e) {
            return false;
        }
    }
}
